import React from "react";
import {
  useCurrentFrame,
  useVideoConfig,
  AbsoluteFill,
  spring,
  interpolate,
} from '../remotionShim';
import { makeLoadFont } from '../googleFonts';
const loadMontserrat = makeLoadFont('Montserrat');
const loadRussoOne = makeLoadFont('RussoOne');

// Initialize fonts at module level
const { fontFamily: montserratFamily } = loadMontserrat();
const { fontFamily: russoFamily } = loadRussoOne();



export type SlotDenomLowerThirdProps = Record<string, any>;

const SlotDenomLowerThird: React.FC<SlotDenomLowerThirdProps> = ({
  backgroundColor = "#000000",
  transparentBackground = true,
  durationInSeconds = 8,
  accentColor = "#FFD700", // Casino Gold
  panelColor = "#1A1A1A",
  textColor = "#FFFFFF",
  labelText = "DENOMINATION",
  subLabelText = "CHANGE",
  denominations = ["$0.10", "$0.50", "$1.00", "$5.00", "$10.00", "$25.00"],
}) => {
  const frame = useCurrentFrame();
  const { fps, width, height } = useVideoConfig();

  // Background transparency logic
  const bgColor = transparentBackground ? `${backgroundColor}00` : backgroundColor;
  
  // Total frames
  const totalFrames = Math.round(durationInSeconds * fps);

  // Responsive sizing
  const panelHeight = height * 0.16;
  const itemHeight = panelHeight * 0.7;
  const paddingX = width * 0.02;
  const paddingY = height * 0.02;

  // Repeat the sequence to create a realistic, long "slot spin" before stopping on the last item
  const paddedSequence = [...denominations, ...denominations, ...denominations];
  
  // -- ANIMATION TIMINGS --
  // 1. Lower Third slides in
  const entrySpring = spring({
    frame,
    fps,
    config: { damping: 14, mass: 1.2 },
  });

  // 2. Reel spins (starts after panel is visible)
  const reelStartFrame = 35;
  const reelSpring = spring({
    frame: frame - reelStartFrame,
    fps,
    config: { 
      damping: 18, 
      mass: 3, 
      stiffness: 80 
    },
  });

  // 3. Lower Third slides out
  const exitStartFrame = totalFrames - 40;
  const exitSpring = spring({
    frame: frame - exitStartFrame,
    fps,
    config: { damping: 14, mass: 1.2 },
  });

  // -- CALCULATIONS --
  // Entry/Exit X Position
  const startX = -width * 0.6;
  const activeX = width * 0.05;
  
  // Calculate current X by composing entry and exit
  // Interpolate entry: startX -> activeX
  // Interpolate exit: 0 -> (startX - activeX) to push it back off screen
  const entryX = interpolate(entrySpring, [0, 1], [startX, activeX]);
  const exitDelta = interpolate(exitSpring, [0, 1], [0, startX - activeX - 100]); // -100 ensures it goes fully off
  const currentX = entryX + exitDelta;

  // Reel Scroll Y Position
  const maxScroll = (paddedSequence.length - 1) * itemHeight;
  const scrollY = interpolate(reelSpring, [0, 1], [0, -maxScroll]);

  // Motion Blur Effect (Vertical blur based on spin progress)
  const blurAmount = interpolate(
    reelSpring,
    [0, 0.1, 0.9, 1],
    [0, 12, 12, 0],
    { extrapolateLeft: "clamp", extrapolateRight: "clamp" }
  );

  // Glow pulse effect for the accent color
  const pulse = interpolate(
    Math.sin(frame * 0.1),
    [-1, 1],
    [0.5, 1]
  );

  return (
    <AbsoluteFill style={{ backgroundColor: bgColor }}>
      
      {/* Main Lower Third Container */}
      <div
        style={{
          position: "absolute",
          bottom: height * 0.08,
          left: currentX,
          display: "flex",
          flexDirection: "row",
          alignItems: "stretch",
          backgroundColor: panelColor,
          border: `3px solid ${accentColor}`,
          borderRadius: height * 0.02,
          padding: `${paddingY}px ${paddingX}px`,
          boxShadow: `0 20px 40px rgba(0,0,0,0.6), 0 0 ${20 * pulse}px ${accentColor}60`,
          height: panelHeight,
        }}
      >
        {/* Left Side: Labels */}
        <div
          style={{
            display: "flex",
            flexDirection: "column",
            justifyContent: "center",
            marginRight: width * 0.03,
            borderRight: `2px solid ${accentColor}40`,
            paddingRight: width * 0.03,
          }}
        >
          <span
            style={{
              fontFamily: montserratFamily,
              color: accentColor,
              fontSize: height * 0.025,
              fontWeight: 900,
              letterSpacing: 4,
              textTransform: "uppercase",
              textShadow: `0 0 10px ${accentColor}80`,
            }}
          >
            {labelText}
          </span>
          <span
            style={{
              fontFamily: montserratFamily,
              color: textColor,
              fontSize: height * 0.035,
              fontWeight: 700,
              opacity: 0.8,
              letterSpacing: 2,
              marginTop: 4,
            }}
          >
            {subLabelText}
          </span>
        </div>

        {/* Right Side: Slot Reel Mechanism */}
        <div
          style={{
            display: "flex",
            alignItems: "center",
            position: "relative",
          }}
        >
          {/* Payline Indicator (Left triangle) */}
          <div
            style={{
              width: 0,
              height: 0,
              borderTop: `${height * 0.015}px solid transparent`,
              borderBottom: `${height * 0.015}px solid transparent`,
              borderLeft: `${height * 0.02}px solid ${accentColor}`,
              position: "absolute",
              left: -height * 0.01,
              zIndex: 10,
              filter: `drop-shadow(0 0 5px ${accentColor})`,
            }}
          />

          {/* Payline Indicator (Right triangle) */}
          <div
            style={{
              width: 0,
              height: 0,
              borderTop: `${height * 0.015}px solid transparent`,
              borderBottom: `${height * 0.015}px solid transparent`,
              borderRight: `${height * 0.02}px solid ${accentColor}`,
              position: "absolute",
              right: -height * 0.01,
              zIndex: 10,
              filter: `drop-shadow(0 0 5px ${accentColor})`,
            }}
          />

          {/* The Reel Window */}
          <div
            style={{
              height: itemHeight,
              width: width * 0.18,
              backgroundColor: "#0A0A0A",
              borderRadius: height * 0.01,
              overflow: "hidden",
              position: "relative",
              border: `2px inset ${accentColor}50`,
            }}
          >
            {/* The Moving Strip of Numbers */}
            <div
              style={{
                display: "flex",
                flexDirection: "column",
                transform: `translateY(${scrollY}px)`,
                filter: `blur(0px ${blurAmount}px)`,
                willChange: "transform, filter",
              }}
            >
              {paddedSequence.map((denom, index) => (
                <div
                  key={`${index}-${denom}`}
                  style={{
                    height: itemHeight,
                    display: "flex",
                    alignItems: "center",
                    justifyContent: "center",
                    width: "100%",
                  }}
                >
                  <span
                    style={{
                      fontFamily: russoFamily,
                      fontSize: itemHeight * 0.75,
                      color: textColor,
                      textShadow: "0 4px 10px rgba(0,0,0,0.8)",
                      lineHeight: 1,
                    }}
                  >
                    {denom}
                  </span>
                </div>
              ))}
            </div>

            {/* Cylinder/Vignette Overlay to make it look round */}
            <div
              style={{
                position: "absolute",
                top: 0,
                left: 0,
                right: 0,
                bottom: 0,
                boxShadow: `
                  inset 0px ${height * 0.02}px ${height * 0.02}px -${height * 0.01}px rgba(0,0,0,0.9),
                  inset 0px -${height * 0.02}px ${height * 0.02}px -${height * 0.01}px rgba(0,0,0,0.9)
                `,
                pointerEvents: "none",
                zIndex: 5,
              }}
            />
            
            {/* Glossy Reflection Highlight */}
            <div
               style={{
                  position: "absolute",
                  top: 0,
                  left: 0,
                  right: 0,
                  height: "40%",
                  background: "linear-gradient(180deg, rgba(255,255,255,0.15) 0%, rgba(255,255,255,0) 100%)",
                  pointerEvents: "none",
                  zIndex: 6,
               }}
            />
          </div>
        </div>
      </div>
    </AbsoluteFill>
  );
};

export default SlotDenomLowerThird;